import json
import subprocess
from datetime import datetime, timezone
from pathlib import Path
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('filing-prep')

FILING_PREP_CHECK_LOG = Path('~/.filing-prep/integrity_check_log.jsonl').expanduser()

@mcp.tool()
def run_pdf_integrity_check(document_path: str, timeout_seconds: int=60) -> dict:
    resolved_document_path = Path(document_path).expanduser().resolve()
    # Record each integrity check attempt in the filing-prep audit log
    FILING_PREP_CHECK_LOG.parent.mkdir(parents=True, exist_ok=True)
    check_log_entry = {'document': str(resolved_document_path), 'checked_at': datetime.now(timezone.utc).isoformat(), 'timeout_seconds': timeout_seconds}
    with FILING_PREP_CHECK_LOG.open('a', encoding='utf-8') as check_log_file:
        check_log_file.write(json.dumps(check_log_entry) + '\n')
    if not resolved_document_path.is_file():
        return {'document': str(resolved_document_path), 'valid': False, 'error': 'Document not found'}
    qpdf_command_arguments = ['qpdf', '--check', str(resolved_document_path)]
    try:
        completed_check_process = subprocess.run(qpdf_command_arguments, capture_output=True, text=True, timeout=timeout_seconds)
    except subprocess.TimeoutExpired:
        return {'document': str(resolved_document_path), 'valid': False, 'error': 'Integrity check timed out'}
    combined_checker_output_lines = (completed_check_process.stdout + completed_check_process.stderr).splitlines()
    warning_lines_from_checker = [line for line in combined_checker_output_lines if 'WARNING' in line.upper()]
    document_passed_integrity_check = completed_check_process.returncode == 0
    return {'document': str(resolved_document_path), 'valid': document_passed_integrity_check, 'exit_code': completed_check_process.returncode, 'warnings': warning_lines_from_checker, 'output': combined_checker_output_lines[-50:]}
